function Emvicy_cookieExists(sCookieName){var aCookie=document.cookie.split(';');for(iCnt=0;iCnt<aCookie.length;iCnt++){if(aCookie[iCnt].split('=')[0].trim()==sCookieName){return true;};}}
document.addEventListener("DOMContentLoaded",function(event){var sCookieName='Emvicy_cookieConsent';if(undefined===Emvicy_cookieExists(sCookieName)){$('#'+sCookieName).fadeIn();}
$('#'+sCookieName+' button').on('click',function(oEvent){if(true===$('#'+sCookieName+' input').is(':checked')){document.cookie=sCookieName+"=true; expires=365; path='/'; SameSite=None; Secure;";$('#'+sCookieName).fadeOut(function(){'slow',location.reload();});}});function Emvicy_dragElement(sElementId){function Emvicy_closeDragElement(){document.onmouseup=null;document.onmousemove=null;}
function Emvicy_elementDrag(oEvent){oEvent=oEvent||window.event;oEvent.preventDefault();iPos1=iPos3-oEvent.clientX;iPos2=iPos4-oEvent.clientY;iPos3=oEvent.clientX;iPos4=oEvent.clientY;oElement.style.top=(oElement.offsetTop-iPos2)+"px";oElement.style.left=(oElement.offsetLeft-iPos1)+"px";localStorage.setItem(sElementId,'{"top":'+(oElement.offsetTop-iPos2)+',"left":'+(oElement.offsetLeft-iPos1)+'}');}
function Emvicy_dragMouseDown(oEvent){oEvent=oEvent||window.event;oEvent.preventDefault();iPos3=oEvent.clientX;iPos4=oEvent.clientY;document.onmouseup=Emvicy_closeDragElement;document.onmousemove=Emvicy_elementDrag;}
function Emvicy_dragRestore(oElement){var sPosition=localStorage.getItem(oElement.id);(null===sPosition)?sPosition='{"top":'+((window.innerHeight/4))+',"left":'+((window.innerWidth/4))+'}':false;var oPosition=JSON.parse(sPosition);oElement.style.top=oPosition.top+'px';oElement.style.left=oPosition.left+'px';oElement.style.display='block';}
var oElement=document.getElementById(sElementId);var iPos1=0,iPos2=0,iPos3=0,iPos4=0;Emvicy_dragRestore(oElement);oElement.onmousedown=Emvicy_dragMouseDown;}
for(var oElement of document.getElementsByClassName('emvicy_draggable')){Emvicy_dragElement(oElement.id);}});